import heapq, math

def weight(noncomp, U=3.0, C=10.0):
    # 비준수율(안내를 안 따른 비율) 0 → 약 1배, 1 → 약 (1+U)배
    return 1 + U / (1 + math.exp(-C * (noncomp - 0.5)))

def dijkstra(graph, src, dst):
    dist, prev, pq = {src: 0.0}, {}, [(0.0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if u == dst:
            break
        if d > dist.get(u, 1e18):
            continue
        for v, cost in graph.get(u, []):
            if d + cost < dist.get(v, 1e18):
                dist[v], prev[v] = d + cost, u
                heapq.heappush(pq, (d + cost, v))
    path = [dst]
    while path[-1] != src:
        path.append(prev[path[-1]])
    return path[::-1], round(dist[dst], 2)

minutes = {("집", "판교IC"): 5, ("집", "성남IC"): 5, ("판교IC", "회사"): 1, ("성남IC", "회사"): 2}
for label, nc in [("이탈 거의 없음", {}), ("판교IC→회사 이탈 80%", {("판교IC", "회사"): 0.8})]:
    g = {}
    for (a, b), t in minutes.items():
        g.setdefault(a, []).append((b, t * weight(nc.get((a, b), 0.0))))
    print(label, dijkstra(g, "집", "회사"))

